func newEC2StartInstancesCmd() *cobra.Command {
	var instanceIds []string
	var additionalInfo string
	var dryRun bool

	cmd := &cobra.Command{
		Use:   "start-instances",
		Short: "StartInstances",
		RunE: func(cmd *cobra.Command, _ []string) error {
			cfg, err := newAWSConfig(cmd.Context())
			if err != nil {
				return err
			}

			client := ec2.NewFromConfig(cfg, func(o *ec2.Options) {
				o.BaseEndpoint = aws.String(endpointURL)
			})

			input := &ec2.StartInstancesInput{}

			if len(instanceIds) > 0 {
				input.InstanceIds = instanceIds
			}

			if additionalInfo != "" {
				input.AdditionalInfo = aws.String(additionalInfo)
			}

			if dryRun {
				input.DryRun = aws.Bool(dryRun)
			}

			out, err := client.StartInstances(cmd.Context(), input)
			if err != nil {
				return fmt.Errorf("start-instances failed: %w", err)
			}

			if err := writeOutput(out); err != nil {
				return err
			}

			return nil
		},
	}

	cmd.Flags().StringArrayVar(&instanceIds, "instance-ids", nil, "Instance ids")

	cmd.Flags().StringVar(&additionalInfo, "additional-info", "", "Additional info")

	cmd.Flags().BoolVar(&dryRun, "dry-run", false, "Dry run")

	cmd.Flags().String("region", "", "Region override (ignored)")

	return cmd
}

